  "verdict": "NEEDS_WORK",
  "checks": [
    {
      "id": "RISK-APPROPRIATE",
      "result": "PASS",
      "severity": "Major",
      "finding": "tasks.md classifies contract, authorization, executor, observation, protected dispatch and public-entry changes as high (T-002–T-007, T-009–T-011). Maintenance integration T-001 and documentation/release integration T-008 are medium; neither introduces cloud-write authority."
    },
    {
      "id": "HIGH-CRITICAL-EVIDENCE",
      "result": "PASS",
      "severity": "Critical",
      "finding": "Every high-risk task explicitly requires committed failing tests before implementation, retained Red→Green evidence and a named independent reviewer verdict in Done When. No critical task is declared."
    },
    {
      "id": "TASK-SIZE",
      "result": "FAIL",
      "severity": "Major",
      "finding": "tasks.md T-004 and T-005 each bundle more than three distinct implementation areas: owner-aware routing and upstream locks, a real compiled/synthesized infrastructure example, guarded prepare/apply execution and preview policy, and timeout/reconcile/no-op lifecycle behavior. Their first three Done When bullets conceal numerous independently verifiable outcomes across AC-002/003/004/006/007/009. These are whole-provider deliveries rather than single focused-session units; split routing/local validation/examples from credentialed execution and recovery, preserving ordered shared-test ownership."
    },
    {
      "id": "EDGE-CASE-COVERAGE",
      "result": "PASS",
      "severity": "Major",
      "finding": "acceptance-tests.md AC-001–AC-012 cover stale anchors, ownership conflicts, missing backup, input mutation, denied approval, replay/timeouts, destructive brownfield changes, unsupported profiles, unhealthy/stale observations, evidence tampering and unavailable host authentication. Functional tasks bind these scenarios in Done When."
    },
    {
      "id": "TEST-TYPE-MATCH",
      "result": "PASS",
      "severity": "Major",
      "finding": "No standalone test-only task is declared. Embedded verification aligns with design.md Unit and Integration Boundaries: router/contracts/reducer checks use isolated inputs; admission/executor/collector and installed-entry checks cross component boundaries; real synthesis and live sandbox evidence remain separately classified. Acceptance checks cite AC IDs."
    },
    {
      "id": "ROLLBACK-PLAN",
      "result": "PASS",
      "severity": "Major",
      "finding": "Every high-risk task includes a Done When item requiring documented and tested rollback with hashes and baseline output. The shared rollback section requires disposable-checkout restoration, disabling defective cloud entry/workflow paths and separately authorized cloud cleanup."
    },
    {
      "id": "SCOPE-DISJOINT",
      "result": "PASS",
      "severity": "Major",
      "finding": "Shared execution tests are ordered T-003→T-004→T-005; provider collectors follow both adapters in T-006; verification-suite changes are ordered T-006→T-009→T-010. T-011 follows T-001 for shared CI drivers and T-007 for installed entry points. Lifecycle rules additionally prohibit simultaneous implementation tasks."
    },
    {
      "id": "DEPENDENCY-OVERLAP",
      "result": "PASS",
      "severity": "Major",
      "finding": "Blockers establish contracts→admission→provider lifecycle→observations→protected profiles→dependency receipts→packaging→host integration→release. Task Goals identify consumed artifacts, including T-005's shared CLI/harness from T-004 and T-010's selected-profile receipts from T-009; packaging integrates the completed runtime before installed-entry trials."
    },
    {
      "id": "BUGFIX-DIAGNOSTIC-PATH",
      "result": "PASS",
      "severity": "Major",
      "finding": "T-001 Goal requires diagnosing the historical stale-line failure before further fixes. Done When preserves the exact failure log, diagnoses the section reference, names python3 -B tests/sdd-domain-multitarget-foundation.tests.py and requires removal/relocation/duplicate-heading/path-escape regressions plus historical-byte comparison."
    }
  ],
  "findings": [
    {
      "check_id": "TASK-SIZE",
      "severity": "Major",
      "task_id": "T-004",
      "finding": "tasks.md T-004 and T-005 each combine owner-aware routing/upstream locks, real IaC example synthesis, guarded prepare/apply and preview policy, and timeout/reconcile/no-op lifecycle implementation. Done When bullets 1–3 aggregate independently verifiable outcomes across AC-002/003/004/006/007/009. This prevents focused-session implementation and independently gated intermediate completion. Split each provider delivery into ordered routing/local-validation/example and execution/recovery units, with explicit ownership of shared tests."
    }
  ]
